  A.svc = (x) => { const [cid, sid] = x.split(':'); S.svc[cid] = sid; route(); };
  // DECISION (backend owner): reported_user_id is the reported person's USER id. Public cards expose only the profile id, so until the API names the two id types separately the UI sends the profile id and the backend must map it to the user. See docs/02-handoff.md → Decisions.
  A.rep = (id) => dlg(`<h2 id="dt">Shikoyat</h2><form data-f="report" data-t="${esc(id)}" class="col" novalidate style="margin-top:12px">${C.Field('category', 'Sabab', { options: [['', 'Tanlang…'], ...Object.entries(L.REPORT_CATS)], required: true })}${C.Field('description', 'Izoh', { area: true, required: true, max: 4000 })}<p class="cap mu">Moderatsiya koʻrib chiqadi. Favqulodda xizmatlar chaqirilmaydi.</p><div id="fe" role="alert"></div><button class="btn full" type="submit">Yuborish</button><button class="btn sec full" type="button" data-a="close">Bekor qilish</button></form>`);
